import java.io.*;
import java.util.Scanner;
public class JWorkHours1 {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        System.out.println("Adkhil ism al-malaf:");
        String name = scan.next();
        JWorkHours1 jwh = new JWorkHours1();
        jwh.reportWorkHours(name);
    }
    //Khatwa 1: Ta'reef al-method allati taamel ma3a malaf al-muwazzafeen
    public void reportWorkHours(String fileName) {
        //Khatwa 1.1: Ihtiwa al-kod allathee qad yarmee istithna'a daakhil blok try
        try {
            //Khatwa 1.1.1: Laff BufferedReader hawl FileReader
            FileReader fr = new FileReader(fileName); 
            BufferedReader br = new BufferedReader(fr); 
            //Khatwa 1.1.2: Istakhdim BufferedReader liqira'at satar wahid fi al-marrah
            String line = null;
            while ( ( line = br.readLine() ) != null) {
                String[] tokens = line.split(" ");
                String name = tokens[0];
                double total = 0.0;
                for (int i = 1; i < tokens.length; i++ ) {
                    try {
                        total += Double.parseDouble(tokens[i]);
                    } catch (  NumberFormatException ex ) {
                        System.out.println("Khata fi al-sa'a.");
                    }
                }
                System.out.println("Majmu' al-saat allati 'amalaha " + name  + " = " + total);
            }     
            //Khatwa 1.1.3: Islaq BufferedReader al-murtaabit bil-malaf
            br.close();
        }
        //Khatwa 1.2: Mu'alajah jami' al-istithna'at al-mumkin an tudfa' fii blok try
        catch (FileNotFoundException ex) {
            System.out.println("Al-malaf lam yujad");
        } catch (IOException ex ) {
            System.out.println("Mushkila ma'a al-malaf!");
        }
    }
}
